insert into public.student_surveys (id,title_ru,title_uz,title_en,description_ru,description_uz,description_en,status) values ('5c07785b-d196-4c25-adb6-d04b67c8af6b','Качество преподавания и условия обучения — 2026/2027','O‘qitish sifati va ta’lim olish sharoitlari — 2026/2027','Teaching quality and learning conditions — 2026/2027','Уважаемые студенты! Просим вас принять участие в опросе о качестве преподавания и условиях обучения в СБУМИПТК в 2026/2027 учебном году. Ваши ответы помогут определить, что необходимо улучшить в образовательном процессе и среде института. Пожалуйста, отвечайте на основании личного опыта обучения в текущем учебном году. Заполнение анкеты займёт 3–5 минут.','Hurmatli talabalar! Sizni Toshkent shahridagi Belarus–O‘zbekiston qo‘shma tarmoqlararo amaliy texnik kvalifikatsiyalar institutida 2026/2027-o‘quv yilidagi o‘qitish sifati va ta’lim olish sharoitlari haqidagi so‘rovda ishtirok etishga taklif qilamiz. Javoblaringiz ta’lim jarayoni va institut muhitida nimalarni yaxshilash zarurligini aniqlashga yordam beradi. Iltimos, joriy o‘quv yilidagi shaxsiy ta’lim tajribangiz asosida javob bering. So‘rovnomani to‘ldirish 3–5 daqiqa vaqt oladi.','Dear students, please take part in this survey on teaching quality and learning conditions at the Belarus–Uzbekistan Joint Intersectoral Institute of Applied Technical Qualifications in Tashkent in the 2026/2027 academic year. Your answers will help identify improvements needed in teaching and the Institute’s learning environment. Please answer based on your personal experience during the current academic year. The survey takes 3–5 minutes to complete.','published') on conflict (id) do nothing;
insert into public.student_survey_questions (id,survey_id,question_type,prompt_ru,prompt_uz,prompt_en,options,required,sort_order) values ('f2494b23-44c9-4530-b0f7-de9e5d8a737c','5c07785b-d196-4c25-adb6-d04b67c8af6b','single','Понятно ли преподаватели объясняют учебный материал?','O‘qituvchilar o‘quv materialini tushunarli tarzda tushuntiradilarmi?','Do your teachers explain the course material clearly?','[{"ru": "Да", "uz": "Ha", "en": "Yes"}, {"ru": "Скорее да", "uz": "Ko‘proq ha", "en": "Mostly yes"}, {"ru": "Скорее нет", "uz": "Ko‘proq yo‘q", "en": "Mostly no"}, {"ru": "Нет", "uz": "Yo‘q", "en": "No"}, {"ru": "Затрудняюсь ответить", "uz": "Javob berishga qiynalaman", "en": "Unable to say"}]',true,0) on conflict (id) do nothing;
