insert into public.student_survey_questions (id,survey_id,question_type,prompt_ru,prompt_uz,prompt_en,options,required,sort_order) values ('1ca43c8d-054c-409f-a53c-10238e768e15','5c07785b-d196-4c25-adb6-d04b67c8af6b','single','Получаете ли вы помощь преподавателей при трудностях в обучении?','O‘qishda qiyinchiliklarga duch kelganingizda o‘qituvchilardan yordam olasizmi?','Do you receive help from teachers when you experience difficulties with your studies?','[{"ru": "Да", "uz": "Ha", "en": "Yes"}, {"ru": "Скорее да", "uz": "Ko‘proq ha", "en": "Mostly yes"}, {"ru": "Скорее нет", "uz": "Ko‘proq yo‘q", "en": "Mostly no"}, {"ru": "Нет", "uz": "Yo‘q", "en": "No"}, {"ru": "Затрудняюсь ответить", "uz": "Javob berishga qiynalaman", "en": "Unable to say"}]',true,7) on conflict (id) do nothing;
