insert into public.student_survey_questions (id,survey_id,question_type,prompt_ru,prompt_uz,prompt_en,options,required,sort_order) values ('a558c521-df45-4318-af53-681d44ea5862','5c07785b-d196-4c25-adb6-d04b67c8af6b','single','Сталкивались ли вы лично в процессе обучения в 2026/2027 учебном году с ситуациями, которые, по вашему мнению, могли иметь коррупционные признаки?','2026/2027-o‘quv yilida ta’lim olish jarayonida, sizning fikringizcha, korrupsiyaga oid belgilar bo‘lishi mumkin bo‘lgan holatlarga shaxsan duch keldingizmi?','During your studies in the 2026/2027 academic year, have you personally encountered situations that, in your opinion, may have shown signs of corruption?','[{"ru": "Нет", "uz": "Yo‘q", "en": "No"}, {"ru": "Да", "uz": "Ha", "en": "Yes"}, {"ru": "Предпочитаю не отвечать", "uz": "Javob bermaslikni afzal ko‘raman", "en": "Prefer not to answer"}]',true,10) on conflict (id) do nothing;
insert into public.student_survey_questions (id,survey_id,question_type,prompt_ru,prompt_uz,prompt_en,options,required,sort_order) values ('71c4adaf-6be6-4f73-9551-5e6dc74d14ad','5c07785b-d196-4c25-adb6-d04b67c8af6b','text','Что необходимо улучшить в преподавании или условиях обучения в первую очередь?','O‘qitish sifati yoki ta’lim olish sharoitlarida birinchi navbatda nimalarni yaxshilash kerak?','What should be improved first in teaching or learning conditions?','[]',false,11) on conflict (id) do nothing;
